func (m OrderedMap[K, V]) MarshalJSON() ([]byte, error) {
	if len(m.mp) == 0 {
		return []byte("{}"), nil
	}
	var buf bytes.Buffer
	buf.WriteByte('{')
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)

	for i, k := range m.keys {
		if i > 0 {
			buf.WriteByte(',')
		}

		keyString, err := resolveKeyName(reflect.ValueOf(k))
		if err != nil {
			return nil, err
		}

		if err := enc.Encode(keyString); err != nil {
			return nil, err
		}

		buf.WriteByte(':')

		if err := enc.Encode(m.mp[k]); err != nil {
			return nil, err
		}
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func isRightSideOfQualifiedNameOrPropertyAccess(node *ast.Node) bool {
	parent := node.Parent
	switch parent.Kind {
	case ast.KindQualifiedName:
		return parent.AsQualifiedName().Right == node
	case ast.KindPropertyAccessExpression:
		return parent.AsPropertyAccessExpression().Name() == node
	case ast.KindMetaProperty:
		return parent.AsMetaProperty().Name() == node
	}
	return false
}

