func runTraceBaseline(t *testing.T, test traceTestCase) {
	t.Run(test.name, func(t *testing.T) {
		t.Parallel()

		host := newVFSModuleResolutionHost(test.files, test.currentDirectory)
		resolver := module.NewResolver(host, test.compilerOptions)

		for _, call := range test.calls {
			doCall(t, resolver, call, false /*skipLocations*/)
			if t.Failed() {
				t.FailNow()
			}
		}

		t.Run("concurrent", func(t *testing.T) {
			concurrentHost := newVFSModuleResolutionHost(test.files, test.currentDirectory)
			concurrentResolver := module.NewResolver(concurrentHost, test.compilerOptions)

			var wg sync.WaitGroup
			for _, call := range test.calls {
				wg.Add(1)
				go func() {
					defer wg.Done()
					doCall(t, concurrentResolver, call, true /*skipLocations*/)
				}()
			}

			wg.Wait()
		})

		if test.trace {
			t.Run("trace", func(t *testing.T) {
				var buf bytes.Buffer
				encoder := json.NewEncoder(&buf)
				encoder.SetIndent("", "    ")
				encoder.SetEscapeHTML(false)
				if err := encoder.Encode(host.traces); err != nil {
					t.Fatal(err)
				}
				baseline.Run(
					t,
					tspath.RemoveFileExtension(test.name)+".trace.json",
					sanitizeTraceOutput(buf.String()),
					baseline.Options{Subfolder: "module/resolver"},
				)
			})
		}
	})
}

func UnmangleScopedPackageName(packageName string) string {
	idx := strings.Index(packageName, "__")
	if idx != -1 {
		return "@" + packageName[:idx] + "/" + packageName[idx+2:]
	}
	return packageName
}

func getPreferredEnding(
	prefs UserPreferences,
	host ModuleSpecifierGenerationHost,
	compilerOptions *core.CompilerOptions,
	importingSourceFile SourceFileForSpecifierGeneration,
	oldImportSpecifier string,
	resolutionMode core.ResolutionMode,
) ModuleSpecifierEnding {
	if len(oldImportSpecifier) > 0 {
		if tspath.HasJSFileExtension(oldImportSpecifier) {
			return ModuleSpecifierEndingJsExtension
		}
		if strings.HasSuffix(oldImportSpecifier, "/index") {
			return ModuleSpecifierEndingIndex
		}
	}
	if resolutionMode == core.ResolutionModeNone {
		// !!! TODO: proper import resolution mode support
		// resolutionMode = host.GetDefaultResolutionModeForFile(importingSourceFile, compilerOptions)
	}
	return getModuleSpecifierEndingPreference(
		prefs.ImportModuleSpecifierEndingPreference,
		resolutionMode,
		compilerOptions,
		importingSourceFile,
	)
}

