func (s *Service) OnWatchedFilesChanged(ctx context.Context, changes []*lsproto.FileEvent) error {
	for _, change := range changes {
		fileName := ls.DocumentURIToFileName(change.Uri)
		path := s.toPath(fileName)
		if project, ok := s.configuredProjects[path]; ok {
			// tsconfig of project
			if err := s.onConfigFileChanged(project, change.Type); err != nil {
				return fmt.Errorf("error handling config file change: %w", err)
			}
		} else if _, ok := s.openFiles[path]; ok {
			// open file
			continue
		} else if info := s.GetScriptInfoByPath(path); info != nil {
			// closed existing file
			if change.Type == lsproto.FileChangeTypeDeleted {
				s.handleDeletedFile(info, true /*deferredDelete*/)
			} else {
				info.deferredDelete = false
				info.delayReloadNonMixedContentFile()
				// !!! s.delayUpdateProjectGraphs(info.containingProjects, false /*clearSourceMapperCache*/)
				// !!! s.handleSourceMapProjects(info)
			}
		} else {
			for _, project := range s.configuredProjects {
				project.onWatchEventForNilScriptInfo(fileName)
			}
		}
	}

	client := s.host.Client()
	if client != nil {
		return client.RefreshDiagnostics(ctx)
	}

	return nil
}

func (s *Service) onConfigFileChanged(project *Project, changeKind lsproto.FileChangeType) error {
	wasDeferredClose := project.deferredClose
	switch changeKind {
	case lsproto.FileChangeTypeCreated:
		if wasDeferredClose {
			project.deferredClose = false
		}
	case lsproto.FileChangeTypeDeleted:
		project.deferredClose = true
	}

	if !project.deferredClose {
		project.pendingReload = PendingReloadFull
		project.markAsDirty()
	}
	project.updateGraph()
	return nil
}

func (s *Service) updateProjectGraphs(projects []*Project, clearSourceMapperCache bool) {
	for _, project := range projects {
		if clearSourceMapperCache {
			project.clearSourceMapperCache()
		}
		project.updateGraph()
	}
}

func (s *Service) getConfigFileNameForFile(info *ScriptInfo, findFromCacheOnly bool) string {
	// !!!
	// const fromCache = this.getConfigFileNameForFileFromCache(info, findFromCacheOnly);
	// if (fromCache !== undefined) return fromCache || undefined;
	// if (findFromCacheOnly) return undefined;
	//
	// !!!
	// good grief, this is convoluted. I'm skipping so much stuff right now
	projectRootPath := s.openFiles[info.path]
	if info.isDynamic {
		return ""
	}

	searchPath := tspath.GetDirectoryPath(info.fileName)
	fileName, _ := tspath.ForEachAncestorDirectory(searchPath, func(directory string) (result string, stop bool) {
		tsconfigPath := tspath.CombinePaths(directory, "tsconfig.json")
		if s.configFileExists(tsconfigPath) {
			return tsconfigPath, true
		}
		if strings.HasSuffix(directory, "/node_modules") {
			return "", true
		}
		if projectRootPath != "" && !tspath.ContainsPath(projectRootPath, directory, s.comparePathsOptions) {
			return "", true
		}
		return "", false
	})
	s.logf("getConfigFileNameForFile:: File: %s ProjectRootPath: %s:: Result: %s", info.fileName, s.openFiles[info.path], fileName)
	return fileName
}

func (s *Service) printProjects() {
	if !s.options.Logger.HasLevel(LogLevelNormal) {
		return
	}

	s.options.Logger.StartGroup()
	for _, project := range s.configuredProjects {
		s.Log(project.print(false /*writeFileNames*/, false /*writeFileExpanation*/, false /*writeFileVersionAndText*/))
	}
	for _, project := range s.inferredProjects {
		s.Log(project.print(false /*writeFileNames*/, false /*writeFileExpanation*/, false /*writeFileVersionAndText*/))
	}

	s.Log("Open files: ")
	for path, projectRootPath := range s.openFiles {
		info := s.GetScriptInfoByPath(path)
		s.logf("\tFileName: %s ProjectRootPath: %s", info.fileName, projectRootPath)
		s.Log("\t\tProjects: " + strings.Join(core.Map(info.containingProjects, func(project *Project) string { return project.name }), ", "))
	}
	s.options.Logger.EndGroup()
}

func (s *ScriptInfo) attachToProject(project *Project) bool {
	if !s.isAttached(project) {
		s.containingProjects = append(s.containingProjects, project)
		if project.compilerOptions.PreserveSymlinks != core.TSTrue {
			s.ensureRealpath(project.FS())
		}
		return true
	}
	return false
}

func NewLogger(outputs []io.Writer, file string, level LogLevel) *Logger {
	var o []*bufio.Writer
	for _, w := range outputs {
		o = append(o, bufio.NewWriter(w))
	}
	logger := &Logger{outputs: o, level: level}
	logger.SetFile(file)
	return logger
}

func (l *Logger) StartGroup() {
	if l == nil {
		return
	}
	l.inGroup = true
}

func (l *Logger) EndGroup() {
	if l == nil {
		return
	}
	l.inGroup = false
}

func (l *Logger) Close() {
	if l == nil {
		return
	}
	for _, output := range l.outputs {
		_ = output.Flush()
	}
	if l.fileHandle != nil {
		_ = l.fileHandle.Close()
	}
}

func (l *Logger) msg(s string, messageType string) {
	if l == nil {
		return
	}
	for _, output := range l.outputs {
		header := fmt.Sprintf("%s %d", messageType, l.seq)
		output.WriteString(header)                                      //nolint: errcheck
		output.WriteString(strings.Repeat(" ", max(0, 10-len(header)))) //nolint: errcheck
		output.WriteRune('[')                                           //nolint: errcheck
		output.WriteString(time.Now().Format("15:04:05.000"))           //nolint: errcheck
		output.WriteString("] ")                                        //nolint: errcheck
		output.WriteString(s)                                           //nolint: errcheck
		output.WriteRune('\n')                                          //nolint: errcheck
		output.Flush()
	}
	if !l.inGroup {
		l.seq++
	}
}

func SkipTriviaEx(text string, pos int, options *SkipTriviaOptions) int {
	if ast.PositionIsSynthesized(pos) {
		return pos
	}
	if options == nil {
		options = &SkipTriviaOptions{}
	}

	canConsumeStar := false
	// Keep in sync with couldStartTrivia
	for {
		ch, size := utf8.DecodeRuneInString(text[pos:])
		switch ch {
		case '\r':
			if text[pos+1] == '\n' {
				pos++
			}
			fallthrough
		case '\n':
			pos++
			if options.StopAfterLineBreak {
				return pos
			}
			canConsumeStar = options.InJSDoc
			continue
		case '\t', '\v', '\f', ' ':
			pos++
			continue
		case '/':
			if options.StopAtComments {
				break
			}
			if pos+1 < len(text) {
				if text[pos+1] == '/' {
					pos += 2
					for pos < len(text) {
						ch, size := utf8.DecodeRuneInString(text[pos:])
						if stringutil.IsLineBreak(ch) {
							break
						}
						pos += size
					}
					canConsumeStar = false
					continue
				}
				if text[pos+1] == '*' {
					pos += 2
					for pos < len(text) {
						if text[pos] == '*' && text[pos+1] == '/' {
							pos += 2
							break
						}
						_, size := utf8.DecodeRuneInString(text[pos:])
						pos += size
					}
					canConsumeStar = false
					continue
				}
			}
		case '<', '|', '=', '>':
			if isConflictMarkerTrivia(text, pos) {
				pos = scanConflictMarkerTrivia(text, pos, nil)
				canConsumeStar = false
				continue
			}
		case '#':
			if pos == 0 && isShebangTrivia(text, pos) {
				pos = scanShebangTrivia(text, pos)
				canConsumeStar = false
				continue
			}
		case '*':
			if canConsumeStar {
				pos++
				canConsumeStar = false
				continue
			}
		default:
			if ch > rune(maxAsciiCharacter) && stringutil.IsWhiteSpaceLike(ch) {
				pos += size
				continue
			}
		}
		return pos
	}
}

func newCompilerTest(
	t *testing.T,
	testName string,
	filename string,
	testContent *testCaseContent,
	namedConfiguration *harnessutil.NamedTestConfiguration,
) *compilerTest {
	basename := tspath.GetBaseFileName(filename)
	configuredName := basename
	if namedConfiguration != nil && namedConfiguration.Name != "" {
		extname := tspath.GetAnyExtensionFromPath(basename, nil, false)
		extensionlessBasename := basename[:len(basename)-len(extname)]
		configuredName = fmt.Sprintf("%s(%s)%s", extensionlessBasename, namedConfiguration.Name, extname)
	}

	var configuration harnessutil.TestConfiguration
	if namedConfiguration != nil {
		configuration = namedConfiguration.Config
	}
	testCaseContentWithConfig := testCaseContentWithConfig{
		testCaseContent: *testContent,
		configuration:   configuration,
	}

	harnessConfig := testCaseContentWithConfig.configuration
	currentDirectory := tspath.GetNormalizedAbsolutePath(harnessConfig["currentdirectory"], srcFolder)

	units := testCaseContentWithConfig.testUnitData
	var toBeCompiled []*harnessutil.TestFile
	var otherFiles []*harnessutil.TestFile
	var tsConfigOptions core.CompilerOptions
	hasNonDtsFiles := core.Some(
		units,
		func(unit *testUnit) bool { return !tspath.FileExtensionIs(unit.name, tspath.ExtensionDts) })
	var tsConfigFiles []*harnessutil.TestFile
	if testCaseContentWithConfig.tsConfig != nil {
		tsConfigOptions = *testCaseContentWithConfig.tsConfig.ParsedConfig.CompilerOptions
		tsConfigFiles = []*harnessutil.TestFile{
			createHarnessTestFile(testCaseContentWithConfig.tsConfigFileUnitData, currentDirectory),
		}
		for _, unit := range units {
			if slices.Contains(
				testCaseContentWithConfig.tsConfig.ParsedConfig.FileNames,
				tspath.GetNormalizedAbsolutePath(unit.name, currentDirectory),
			) {
				toBeCompiled = append(toBeCompiled, createHarnessTestFile(unit, currentDirectory))
			} else {
				otherFiles = append(otherFiles, createHarnessTestFile(unit, currentDirectory))
			}
		}
	} else {
		baseUrl, ok := harnessConfig["baseurl"]
		if ok && !tspath.IsRootedDiskPath(baseUrl) {
			harnessConfig["baseurl"] = tspath.GetNormalizedAbsolutePath(baseUrl, currentDirectory)
		}

		lastUnit := units[len(units)-1]
		// We need to assemble the list of input files for the compiler and other related files on the 'filesystem' (ie in a multi-file test)
		// If the last file in a test uses require or a triple slash reference we'll assume all other files will be brought in via references,
		// otherwise, assume all files are just meant to be in the same compilation session without explicit references to one another.

		if testCaseContentWithConfig.configuration["noimplicitreferences"] != "" ||
			strings.Contains(lastUnit.content, requireStr) ||
			referencesRegex.MatchString(lastUnit.content) {
			toBeCompiled = append(toBeCompiled, createHarnessTestFile(lastUnit, currentDirectory))
			for _, unit := range units[:len(units)-1] {
				otherFiles = append(otherFiles, createHarnessTestFile(unit, currentDirectory))
			}
		} else {
			toBeCompiled = core.Map(units, func(unit *testUnit) *harnessutil.TestFile { return createHarnessTestFile(unit, currentDirectory) })
		}
	}

	result := harnessutil.CompileFiles(
		t,
		toBeCompiled,
		otherFiles,
		harnessConfig,
		&tsConfigOptions,
		currentDirectory,
		testCaseContentWithConfig.symlinks,
	)

	return &compilerTest{
		testName:       testName,
		filename:       filename,
		basename:       basename,
		configuredName: configuredName,
		options:        result.Options,
		harnessOptions: result.HarnessOptions,
		result:         result,
		tsConfigFiles:  tsConfigFiles,
		toBeCompiled:   toBeCompiled,
		otherFiles:     otherFiles,
		hasNonDtsFiles: hasNonDtsFiles,
	}
}

func CompileFiles(
	t *testing.T,
	inputFiles []*TestFile,
	otherFiles []*TestFile,
	testConfig TestConfiguration,
	tsconfigOptions *core.CompilerOptions,
	currentDirectory string,
	symlinks map[string]string,
) *CompilationResult {
	var compilerOptions core.CompilerOptions
	if tsconfigOptions != nil {
		compilerOptions = *tsconfigOptions
	}
	// Set default options for tests
	if compilerOptions.NewLine == core.NewLineKindNone {
		compilerOptions.NewLine = core.NewLineKindCRLF
	}
	if compilerOptions.SkipDefaultLibCheck == core.TSUnknown {
		compilerOptions.SkipDefaultLibCheck = core.TSTrue
	}
	compilerOptions.NoErrorTruncation = core.TSTrue
	harnessOptions := HarnessOptions{UseCaseSensitiveFileNames: true, CurrentDirectory: currentDirectory}

	// Parse harness and compiler options from the test configuration
	if testConfig != nil {
		setOptionsFromTestConfig(t, testConfig, &compilerOptions, &harnessOptions)
	}

	return CompileFilesEx(t, inputFiles, otherFiles, &harnessOptions, &compilerOptions, currentDirectory, symlinks)
}

