func (w *Watcher) start() {
	// if this function is updated, make sure to update `StartForTest` in export_test.go as needed
	if w.configFileName == "" {
		w.host = compiler.NewCompilerHost(w.sys.GetCurrentDirectory(), w.sys.FS(), w.sys.DefaultLibraryPath(), nil)
	}
	w.program = incremental.ReadBuildInfoProgram(w.options, incremental.NewBuildInfoReader(w.host))

	if !w.testing {
		watchInterval := 1000 * time.Millisecond
		if w.options.ParsedConfig.WatchOptions != nil {
			watchInterval = time.Duration(*w.options.ParsedConfig.WatchOptions.Interval) * time.Millisecond
		}
		for {
			w.DoCycle()
			time.Sleep(watchInterval)
		}
	} else {
		// Initial compilation in test mode
		w.DoCycle()
	}
}

func (f *FourslashTest) getBaselineForGroupedLocationsWithFileContents(groupedLocations *collections.MultiMap[lsproto.DocumentUri, *lsproto.Location], options baselineFourslashLocationsOptions) string {
	// We must always print the file containing the marker,
	// but don't want to print it twice at the end if it already
	// found in a file with ranges.
	foundMarker := false

	baselineEntries := []string{}
	err := f.vfs.WalkDir("/", func(path string, d vfs.DirEntry, e error) error {
		if e != nil {
			return e
		}

		if !d.Type().IsRegular() {
			return nil
		}

		fileName := ls.FileNameToDocumentURI(path)
		locations := groupedLocations.Get(fileName)
		if len(locations) == 0 {
			return nil
		}

		content, ok := f.vfs.ReadFile(path)
		if !ok {
			// !!! error?
			return nil
		}

		if options.marker != nil && options.marker.FileName() == path {
			foundMarker = true
		}

		documentSpans := core.Map(locations, func(location *lsproto.Location) *documentSpan {
			return &documentSpan{
				Location: *location,
			}
		})
		baselineEntries = append(baselineEntries, f.getBaselineContentForFile(path, content, documentSpans, nil, options))
		return nil
	})

	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		panic("walkdir error during fourslash baseline: " + err.Error())
	}

	if !foundMarker && options.marker != nil {
		// If we didn't find the marker in any file, we need to add it.
		markerFileName := options.marker.FileName()
		if content, ok := f.vfs.ReadFile(markerFileName); ok {
			baselineEntries = append(baselineEntries, f.getBaselineContentForFile(markerFileName, content, nil, nil, options))
		}
	}

	// !!! foundAdditionalSpan
	// !!! skipDocumentContainingOnlyMarker

	return strings.Join(baselineEntries, "\n\n")
}

func performCompilation(
	sys System,
	config *tsoptions.ParsedCommandLine,
	reportDiagnostic diagnosticReporter,
	extendedConfigCache *collections.SyncMap[tspath.Path, *tsoptions.ExtendedConfigCacheEntry],
	configTime time.Duration,
) CommandLineResult {
	host := compiler.NewCachedFSCompilerHost(sys.GetCurrentDirectory(), sys.FS(), sys.DefaultLibraryPath(), extendedConfigCache)
	// todo: cache, statistics, tracing
	parseStart := sys.Now()
	program := compiler.NewProgram(compiler.ProgramOptions{
		Config:           config,
		Host:             host,
		JSDocParsingMode: ast.JSDocParsingModeParseForTypeErrors,
	})
	parseTime := sys.Now().Sub(parseStart)
	return CommandLineResult{
		Status: emitAndReportStatistics(
			sys,
			program,
			program,
			config,
			reportDiagnostic,
			configTime,
			parseTime,
		),
	}
}

func emitAndReportStatistics(
	sys System,
	programLike compiler.ProgramLike,
	program *compiler.Program,
	config *tsoptions.ParsedCommandLine,
	reportDiagnostic diagnosticReporter,
	configTime time.Duration,
	parseTime time.Duration,
) ExitStatus {
	result := emitFilesAndReportErrors(sys, programLike, reportDiagnostic)
	if result.status != ExitStatusSuccess {
		// compile exited early
		return result.status
	}

	result.configTime = configTime
	result.parseTime = parseTime
	result.totalTime = sys.SinceStart()

	if config.CompilerOptions().Diagnostics.IsTrue() || config.CompilerOptions().ExtendedDiagnostics.IsTrue() {
		var memStats runtime.MemStats
		// GC must be called twice to allow things to settle.
		runtime.GC()
		runtime.GC()
		runtime.ReadMemStats(&memStats)

		reportStatistics(sys, program, result, &memStats)
	}

	if result.emitResult.EmitSkipped && len(result.diagnostics) > 0 {
		return ExitStatusDiagnosticsPresent_OutputsSkipped
	} else if len(result.diagnostics) > 0 {
		return ExitStatusDiagnosticsPresent_OutputsGenerated
	}
	return ExitStatusSuccess
}

