func (l *LanguageService) getDocumentSymbolsForChildren(ctx context.Context, node *ast.Node) []*lsproto.DocumentSymbol {
	var symbols []*lsproto.DocumentSymbol
	addSymbolForNode := func(node *ast.Node, children []*lsproto.DocumentSymbol) {
		symbol := l.newDocumentSymbol(node, children)
		if symbol != nil {
			symbols = append(symbols, symbol)
		}
	}
	var visit func(*ast.Node) bool
	getSymbolsForChildren := func(node *ast.Node) []*lsproto.DocumentSymbol {
		var result []*lsproto.DocumentSymbol
		if node != nil {
			saveSymbols := symbols
			symbols = nil
			node.ForEachChild(visit)
			result = symbols
			symbols = saveSymbols
		}
		return result
	}
	visit = func(node *ast.Node) bool {
		if ctx != nil && ctx.Err() != nil {
			return true
		}
		switch node.Kind {
		case ast.KindClassDeclaration, ast.KindClassExpression, ast.KindInterfaceDeclaration, ast.KindEnumDeclaration:
			addSymbolForNode(node, getSymbolsForChildren(node))
		case ast.KindModuleDeclaration:
			addSymbolForNode(node, getSymbolsForChildren(getInteriorModule(node)))
		case ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction, ast.KindMethodDeclaration, ast.KindGetAccessor,
			ast.KindSetAccessor, ast.KindConstructor:
			addSymbolForNode(node, getSymbolsForChildren(node.Body()))
		case ast.KindVariableDeclaration, ast.KindBindingElement, ast.KindPropertyAssignment, ast.KindPropertyDeclaration:
			name := node.Name()
			if name != nil {
				if ast.IsBindingPattern(name) {
					visit(name)
				} else {
					addSymbolForNode(node, getSymbolsForChildren(node.Initializer()))
				}
			}
		case ast.KindMethodSignature, ast.KindPropertySignature, ast.KindCallSignature, ast.KindConstructSignature, ast.KindIndexSignature,
			ast.KindEnumMember, ast.KindShorthandPropertyAssignment, ast.KindTypeAliasDeclaration:
			addSymbolForNode(node, nil)
		default:
			node.ForEachChild(visit)
		}
		return false
	}
	node.ForEachChild(visit)
	return symbols
}

func TestUntitledReferences(t *testing.T) {
	t.Parallel()
	if !bundled.Embedded {
		t.Skip("bundled files are not embedded")
	}

	// First test the URI conversion functions to understand the issue
	untitledURI := lsproto.DocumentUri("untitled:Untitled-2")
	convertedFileName := ls.DocumentURIToFileName(untitledURI)
	t.Logf("URI '%s' converts to filename '%s'", untitledURI, convertedFileName)

	backToURI := ls.FileNameToDocumentURI(convertedFileName)
	t.Logf("Filename '%s' converts back to URI '%s'", convertedFileName, backToURI)

	if string(backToURI) != string(untitledURI) {
		t.Errorf("Round-trip conversion failed: '%s' -> '%s' -> '%s'", untitledURI, convertedFileName, backToURI)
	}

	// Create a test case that simulates how untitled files should work
	testContent := `let x = 42;

x

x++;`

	// Use the converted filename that DocumentURIToFileName would produce
	untitledFileName := convertedFileName // "^/untitled/ts-nul-authority/Untitled-2"
	t.Logf("Would use untitled filename: %s", untitledFileName)

	// Set up the file system with an untitled file -
	// But use a regular file first to see the current behavior
	files := map[string]string{
		"/Untitled-2.ts": testContent,
	}

	ctx := projecttestutil.WithRequestID(t.Context())
	service, done := createLanguageService(ctx, "/Untitled-2.ts", files)
	defer done()

	// Test the filename that the source file reports
	program := service.GetProgram()
	sourceFile := program.GetSourceFile("/Untitled-2.ts")
	t.Logf("SourceFile.FileName() returns: '%s'", sourceFile.FileName())

	// Calculate position of 'x' on line 3 (zero-indexed line 2, character 0)
	position := 13 // After "let x = 42;\n\n"

	// Call ProvideReferences using the test method
	refs := service.TestProvideReferences("/Untitled-2.ts", position)

	// Log the results
	t.Logf("Input file name: %s", "/Untitled-2.ts")
	t.Logf("Number of references found: %d", len(refs))
	for i, ref := range refs {
		t.Logf("Reference %d: URI=%s, Range=%+v", i+1, ref.Uri, ref.Range)
	}

	// We expect to find 3 references
	assert.Assert(t, len(refs) == 3, "Expected 3 references, got %d", len(refs))

	// Also test definition using ProvideDefinition
	uri := ls.FileNameToDocumentURI("/Untitled-2.ts")
	lspPosition := lsproto.Position{Line: 2, Character: 0}
	definition, err := service.ProvideDefinition(t.Context(), uri, lspPosition)
	assert.NilError(t, err)
	if definition != nil && definition.Locations != nil {
		t.Logf("Definition found: %d locations", len(*definition.Locations))
		for i, loc := range *definition.Locations {
			t.Logf("Definition %d: URI=%s, Range=%+v", i+1, loc.Uri, loc.Range)
		}
	}
}

func ProvideWorkspaceSymbols(ctx context.Context, programs []*compiler.Program, converters *Converters, query string) ([]lsproto.SymbolInformation, error) {
	// Obtain set of non-declaration source files from all active programs.
	var sourceFiles collections.Set[*ast.SourceFile]
	for _, program := range programs {
		for _, sourceFile := range program.SourceFiles() {
			if !sourceFile.IsDeclarationFile {
				sourceFiles.Add(sourceFile)
			}
		}
	}
	// Create DeclarationInfos for all declarations in the source files.
	var infos []DeclarationInfo
	for sourceFile := range sourceFiles.Keys() {
		if ctx != nil && ctx.Err() != nil {
			return []lsproto.SymbolInformation{}, nil
		}
		declarationMap := sourceFile.GetDeclarationMap()
		for name, declarations := range declarationMap {
			score := getMatchScore(name, query)
			if score >= 0 {
				for _, declaration := range declarations {
					infos = append(infos, DeclarationInfo{name, declaration, score})
				}
			}
		}
	}
	// Sort the DeclarationInfos and return the top 256 matches.
	slices.SortFunc(infos, compareDeclarationInfos)
	count := min(len(infos), 256)
	symbols := make([]lsproto.SymbolInformation, count)
	for i, info := range infos[0:count] {
		node := core.OrElse(ast.GetNameOfDeclaration(info.declaration), info.declaration)
		sourceFile := ast.GetSourceFileOfNode(node)
		pos := scanner.SkipTrivia(sourceFile.Text(), node.Pos())
		var symbol lsproto.SymbolInformation
		symbol.Name = info.name
		symbol.Kind = getSymbolKindFromNode(info.declaration)
		symbol.Location = converters.ToLSPLocation(sourceFile, core.NewTextRange(pos, node.End()))
		symbols[i] = symbol
	}
	return symbols, nil
}

func (l *LanguageService) ProvideDocumentSymbols(ctx context.Context, documentURI lsproto.DocumentUri) (lsproto.DocumentSymbolResponse, error) {
	_, file := l.getProgramAndFile(documentURI)
	symbols := l.getDocumentSymbolsForChildren(ctx, file.AsNode())
	return lsproto.SymbolInformationsOrDocumentSymbolsOrNull{DocumentSymbols: &symbols}, nil
}

