func enableVirtualTerminalProcessing() {
	h, err := windows.GetStdHandle(windows.STD_OUTPUT_HANDLE)
	if err != nil || h == windows.InvalidHandle {
		return
	}
	fileType, err := windows.GetFileType(h)
	if err != nil || fileType == windows.FILE_TYPE_CHAR {
		var mode uint32
		if err := windows.GetConsoleMode(h, &mode); err != nil {
			return
		}
		if mode&windows.ENABLE_VIRTUAL_TERMINAL_PROCESSING == 0 {
			_ = windows.SetConsoleMode(h, mode|windows.ENABLE_VIRTUAL_TERMINAL_PROCESSING)
		}
	}
}

func (f *tristateFlag) Set(s string) error {
	v, err := strconv.ParseBool(s)
	if err != nil {
		return errParse
	}
	if v {
		*f = (tristateFlag)(core.TSTrue)
	} else {
		*f = (tristateFlag)(core.TSFalse)
	}
	return nil
}

func (f *tristateFlag) String() string {
	switch core.Tristate(*f) {
	case core.TSTrue:
		return "true"
	case core.TSFalse:
		return "false"
	default:
		return "unset"
	}
}

