		options = &core.CompilerOptions{
			AllowJs:                      core.TSTrue,
			MaxNodeModuleJsDepth:         &depth,
			AllowSyntheticDefaultImports: core.TSTrue,
			SkipLibCheck:                 core.TSTrue,
			NoEmit:                       core.TSTrue,
		}
	}
	return options
}

