func tryGetImportFromModuleSpecifier(node *ast.StringLiteralLike) *ast.Node {
	switch node.Parent.Kind {
	case ast.KindImportDeclaration, ast.KindJSImportDeclaration, ast.KindExportDeclaration:
		return node.Parent
	case ast.KindExternalModuleReference:
		return node.Parent.Parent
	case ast.KindCallExpression:
		if ast.IsImportCall(node.Parent) || ast.IsRequireCall(node.Parent) {
			return node.Parent
		}
		return nil
	case ast.KindLiteralType:
		if !ast.IsStringLiteral(node) {
			return nil
		}
		if ast.IsImportTypeNode(node.Parent.Parent) {
			return node.Parent.Parent
		}
		return nil
	}
	return nil
}

func (r *resolutionState) loadNodeModuleFromDirectoryWorker(ext extensions, candidate string, onlyRecordFailures bool, packageInfo *packagejson.InfoCacheEntry) *resolved {
	var (
		packageFile                      string
		onlyRecordFailuresForPackageFile bool
		versionPaths                     packagejson.VersionPaths
	)
	if packageInfo.Exists() && tspath.ComparePaths(candidate, packageInfo.PackageDirectory, tspath.ComparePathsOptions{UseCaseSensitiveFileNames: r.resolver.host.FS().UseCaseSensitiveFileNames()}) == 0 {
		if file, ok := r.getPackageFile(ext, packageInfo); ok {
			packageFile = file
			onlyRecordFailuresForPackageFile = !r.resolver.host.FS().DirectoryExists(tspath.GetDirectoryPath(file))
		}
	}

	loader := func(extensions extensions, candidate string, onlyRecordFailures bool) *resolved {
		if fromFile := r.loadFileNameFromPackageJSONField(extensions, candidate, packageFile, onlyRecordFailures); !fromFile.shouldContinueSearching() {
			return fromFile
		}

		// Even if `extensions == extensionsDeclaration`, we can still look up a .ts file as a result of package.json "types"
		// !!! should we not set this before the filename lookup above?
		expandedExtensions := extensions
		if extensions == extensionsDeclaration {
			expandedExtensions = extensionsTypeScript | extensionsDeclaration
		}

		// Disable `esmMode` for the resolution of the package path for CJS-mode packages (so the `main` field can omit extensions)
		saveESMMode := r.esmMode
		saveCandidateIsFromPackageJsonField := r.candidateIsFromPackageJsonField
		r.candidateIsFromPackageJsonField = true
		if packageInfo.Exists() && packageInfo.Contents.Type.Value != "module" {
			r.esmMode = false
		}
		result := r.nodeLoadModuleByRelativeName(expandedExtensions, candidate, onlyRecordFailures, false /*considerPackageJson*/)
		r.esmMode = saveESMMode
		r.candidateIsFromPackageJsonField = saveCandidateIsFromPackageJsonField
		return result
	}

	var indexPath string
	if r.isConfigLookup {
		indexPath = tspath.CombinePaths(candidate, "tsconfig")
	} else {
		indexPath = tspath.CombinePaths(candidate, "index")
	}

	if versionPaths.Exists() && (packageFile == "" || tspath.ContainsPath(candidate, packageFile, tspath.ComparePathsOptions{})) {
		var moduleName string
		if packageFile != "" {
			moduleName = tspath.GetRelativePathFromDirectory(candidate, packageFile, tspath.ComparePathsOptions{})
		} else {
			moduleName = tspath.GetRelativePathFromDirectory(candidate, indexPath, tspath.ComparePathsOptions{})
		}
		if r.resolver.traceEnabled() {
			r.resolver.host.Trace(diagnostics.X_package_json_has_a_typesVersions_entry_0_that_matches_compiler_version_1_looking_for_a_pattern_to_match_module_name_2.Format(versionPaths.Version, core.Version, moduleName))
		}
		pathPatterns := tryParsePatterns(versionPaths.GetPaths())
		if result := r.tryLoadModuleUsingPaths(ext, moduleName, candidate, versionPaths.GetPaths(), pathPatterns, loader, onlyRecordFailuresForPackageFile); !result.shouldContinueSearching() {
			if result.packageId.Name != "" {
				// !!! are these asserts really necessary?
				panic("expected packageId to be empty")
			}
			return result
		}
	}

	if packageFile != "" {
		if packageFileResult := loader(ext, packageFile, onlyRecordFailuresForPackageFile); !packageFileResult.shouldContinueSearching() {
			if packageFileResult.packageId.Name != "" {
				// !!! are these asserts really necessary?
				panic("expected packageId to be empty")
			}
			return packageFileResult
		}
	}

	// ESM mode resolutions don't do package 'index' lookups
	if !r.esmMode {
		return r.loadModuleFromFile(ext, indexPath, onlyRecordFailures || !r.resolver.host.FS().DirectoryExists(candidate))
	}
	return continueSearching()
}

func (p *PackageJson) GetVersionPaths(trace func(string)) VersionPaths {
	p.once.Do(func() {
		if p.Fields.TypesVersions.Type == JSONValueTypeNotPresent {
			if trace != nil {
				trace(diagnostics.X_package_json_does_not_have_a_0_field.Format("typesVersions"))
			}
			return
		}
		if p.Fields.TypesVersions.Type != JSONValueTypeObject {
			if trace != nil {
				trace(diagnostics.Expected_type_of_0_field_in_package_json_to_be_1_got_2.Format("typesVersions", "object", p.Fields.TypesVersions.Type.String()))
			}
			return
		}

		if trace != nil {
			trace(diagnostics.X_package_json_has_a_typesVersions_field_with_version_specific_path_mappings.Format("typesVersions"))
		}

		for key, value := range p.Fields.TypesVersions.AsObject().Entries() {
			keyRange, ok := semver.TryParseVersionRange(key)
			if ok {
				if trace != nil {
					trace(diagnostics.X_package_json_has_a_typesVersions_entry_0_that_is_not_a_valid_semver_range.Format(key))
				}
				continue
			}
			if keyRange.Test(&typeScriptVersion) {
				if value.Type != JSONValueTypeObject {
					if trace != nil {
						trace(diagnostics.Expected_type_of_0_field_in_package_json_to_be_1_got_2.Format("typesVersions['"+key+"']", "object", value.Type.String()))
					}
					return
				}
				p.versionPaths = VersionPaths{
					Version:   key,
					pathsJSON: value.AsObject(),
				}
				return
			}
		}

		if trace != nil {
			trace(diagnostics.X_package_json_does_not_have_a_typesVersions_entry_that_matches_version_0.Format(core.VersionMajorMinor))
		}
	})
	return p.versionPaths
}

func (p *Parser) reparseTags(parent *ast.Node, jsDoc []*ast.Node) {
	for _, j := range jsDoc {
		isLast := j == jsDoc[len(jsDoc)-1]
		tags := j.AsJSDoc().Tags
		if tags == nil {
			continue
		}
		for _, tag := range j.AsJSDoc().Tags.Nodes {
			switch tag.Kind {
			case ast.KindJSDocTypedefTag:
				// !!! Don't mark typedefs as exported if they are not in a module
				typeExpression := tag.AsJSDocTypedefTag().TypeExpression
				if typeExpression == nil {
					break
				}
				export := p.factory.NewModifier(ast.KindExportKeyword)
				export.Loc = tag.Loc
				export.Flags = p.contextFlags | ast.NodeFlagsReparsed
				nodes := p.nodeSlicePool.NewSlice(1)
				nodes[0] = export
				modifiers := p.newModifierList(export.Loc, nodes)

				typeParameters := p.gatherTypeParameters(j)

				var t *ast.Node
				switch typeExpression.Kind {
				case ast.KindJSDocTypeExpression:
					t = typeExpression.Type()
				case ast.KindJSDocTypeLiteral:
					// ... (11 lines folded)
					panic("typedef tag type expression should be a name reference or a type expression" + typeExpression.Kind.String())
				}
				typeAlias := p.factory.NewJSTypeAliasDeclaration(modifiers, tag.AsJSDocTypedefTag().Name(), typeParameters, t)
				typeAlias.Loc = core.NewTextRange(tag.Pos(), tag.End())
				typeAlias.Flags = p.contextFlags | ast.NodeFlagsReparsed
				p.reparseList = append(p.reparseList, typeAlias)
			case ast.KindJSDocImportTag:
				importTag := tag.AsJSDocImportTag()
				importClause := importTag.ImportClause.Clone(&p.factory)
				importClause.Flags |= ast.NodeFlagsReparsed
				importClause.AsImportClause().IsTypeOnly = true
				importDeclaration := p.factory.NewJSImportDeclaration(importTag.Modifiers(), importClause, importTag.ModuleSpecifier, importTag.Attributes)
				importDeclaration.Loc = core.NewTextRange(tag.Pos(), tag.End())
				importDeclaration.Flags = p.contextFlags | ast.NodeFlagsReparsed
				p.reparseList = append(p.reparseList, importDeclaration)
				// !!! @overload and other unattached tags (@callback et al) support goes here
			}
			if !isLast {
				continue
			}
			switch tag.Kind {
			case ast.KindJSDocTypeTag:
				// ... (68 lines folded)
		}
	}
}

func (g *NameGenerator) generateNameForNode(node *ast.Node, privateName bool, flags GeneratedIdentifierFlags, prefix string, suffix string) string {
	switch node.Kind {
	case ast.KindIdentifier, ast.KindPrivateIdentifier:
		return g.makeUniqueName(g.GetTextOfNode(node), nil /*checkFn*/, flags.IsOptimistic(), flags.IsReservedInNestedScopes(), privateName, prefix, suffix)
	case ast.KindModuleDeclaration, ast.KindEnumDeclaration:
		if privateName || len(prefix) > 0 || len(suffix) > 0 {
			panic("Generated name for a module or enum cannot be private and may have neither a prefix nor suffix")
		}
		return g.generateNameForModuleOrEnum(node)
	case ast.KindImportDeclaration, ast.KindJSImportDeclaration, ast.KindExportDeclaration:
		if privateName || len(prefix) > 0 || len(suffix) > 0 {
			panic("Generated name for an import or export cannot be private and may have neither a prefix nor suffix")
		}
		return g.generateNameForImportOrExportDeclaration(node)
	case ast.KindFunctionDeclaration, ast.KindClassDeclaration:
		if privateName || len(prefix) > 0 || len(suffix) > 0 {
			panic("Generated name for a class or function declaration cannot be private and may have neither a prefix nor suffix")
		}
		name := node.Name()
		if name != nil && !(g.Context == nil && g.Context.HasAutoGenerateInfo(name)) {
			return g.generateNameForNode(name, false /*privateName*/, flags, "" /*prefix*/, "" /*suffix*/)
		}
		return g.generateNameForExportDefault()
	case ast.KindExportAssignment:
		if privateName || len(prefix) > 0 || len(suffix) > 0 {
			panic("Generated name for an export assignment cannot be private and may have neither a prefix nor suffix")
		}
		return g.generateNameForExportDefault()
	case ast.KindClassExpression:
		if privateName || len(prefix) > 0 || len(suffix) > 0 {
			panic("Generated name for a class expression cannot be private and may have neither a prefix nor suffix")
		}
		return g.generateNameForClassExpression()
	case ast.KindMethodDeclaration, ast.KindGetAccessor, ast.KindSetAccessor:
		return g.generateNameForMethodOrAccessor(node, privateName, prefix, suffix)
	case ast.KindComputedPropertyName:
		return g.makeTempVariableName(tempFlagsAuto, true /*reservedInNestedScopes*/, privateName, prefix, suffix)
	default:
		return g.makeTempVariableName(tempFlagsAuto, false /*reservedInNestedScopes*/, privateName, prefix, suffix)
	}
}

