			expectedNumCtx: 4096,
		},
		{
			name:           "negative context length uses default",
			contextLength:  "-1",
			expectedNumCtx: 2048,
		},
		{
			name:           "zero context length uses default",
			contextLength:  "0",
			expectedNumCtx: 2048,
		},
