async def _construct_dom_tree(
	self,
	eval_page: dict,
) -> tuple[DOMElementNode, SelectorMap]:
	js_node_map = eval_page['map']
	js_root_id = eval_page['rootId']

	selector_map = {}
	node_map = {}

	for id, node_data in js_node_map.items():
		node, children_ids = self._parse_node(node_data)
		if node is None:
			continue

		node_map[id] = node

		if isinstance(node, DOMElementNode) and node.highlight_index is not None:
			selector_map[node.highlight_index] = node

		# NOTE: We know that we are building the tree bottom up
		#       and all children are already processed.
		if isinstance(node, DOMElementNode):
			for child_id in children_ids:
				if child_id not in node_map:
					continue

				child_node = node_map[child_id]

				child_node.parent = node
				node.children.append(child_node)

	html_to_dict = node_map[str(js_root_id)]

	del node_map
	del js_node_map
	del js_root_id

	gc.collect()

	if html_to_dict is None or not isinstance(html_to_dict, DOMElementNode):
		raise ValueError('Failed to parse HTML to dictionary')

	return html_to_dict, selector_map

def is_parent_top_element(self) -> bool:
	if self.parent is None:
		return False
	return self.parent.is_top_element

class DOMElementNode(DOMBaseNode):
	"""
	xpath: the xpath of the element from the last root node (shadow root or iframe OR document if no shadow root or iframe).
	To properly reference the element we need to recursively switch the root node until we find the element (work you way up the tree with `.parent`)
	"""

	tag_name: str
	xpath: str
	attributes: Dict[str, str]
	children: List[DOMBaseNode]
	is_interactive: bool = False
	is_top_element: bool = False
	is_in_viewport: bool = False
	shadow_root: bool = False
	highlight_index: Optional[int] = None
	viewport_coordinates: Optional[CoordinateSet] = None
	page_coordinates: Optional[CoordinateSet] = None
	viewport_info: Optional[ViewportInfo] = None

	def __repr__(self) -> str:
		tag_str = f'<{self.tag_name}'

		# Add attributes
		for key, value in self.attributes.items():
			tag_str += f' {key}="{value}"'
		tag_str += '>'

		# Add extra info
		extras = []
		if self.is_interactive:
			extras.append('interactive')
		if self.is_top_element:
			extras.append('top')
		if self.shadow_root:
			extras.append('shadow-root')
		if self.highlight_index is not None:
			extras.append(f'highlight:{self.highlight_index}')
		if self.is_in_viewport:
			extras.append('in-viewport')

		if extras:
			tag_str += f' [{", ".join(extras)}]'

		return tag_str

	@cached_property
	def hash(self) -> HashedDomElement:
		from browser_use.dom.history_tree_processor.service import (
			HistoryTreeProcessor,
		)

		return HistoryTreeProcessor._hash_dom_element(self)

	def get_all_text_till_next_clickable_element(self, max_depth: int = -1) -> str:
		text_parts = []

		def collect_text(node: DOMBaseNode, current_depth: int) -> None:
			if max_depth != -1 and current_depth > max_depth:
				return

			# Skip this branch if we hit a highlighted element (except for the current node)
			if isinstance(node, DOMElementNode) and node != self and node.highlight_index is not None:
				return

			if isinstance(node, DOMTextNode):
				text_parts.append(node.text)
			elif isinstance(node, DOMElementNode):
				for child in node.children:
					collect_text(child, current_depth + 1)

		collect_text(self, 0)
		return '\n'.join(text_parts).strip()

	@time_execution_sync('--clickable_elements_to_string')
	def clickable_elements_to_string(self, include_attributes: list[str] | None = None) -> str:
		"""Convert the processed DOM content to HTML."""
		formatted_text = []

		def process_node(node: DOMBaseNode, depth: int) -> None:
			if isinstance(node, DOMElementNode):
				# Add element with highlight_index
				if node.highlight_index is not None:
					attributes_str = ''
					text = node.get_all_text_till_next_clickable_element()
					if include_attributes:
						attributes = list(
							set(
								[
									str(value)
									for key, value in node.attributes.items()
									if key in include_attributes and value != node.tag_name
								]
							)
						)
						if text in attributes:
							attributes.remove(text)
						attributes_str = ';'.join(attributes)
					line = f'[{node.highlight_index}]<{node.tag_name} '
					if attributes_str:
						line += f'{attributes_str}'
					if text:
						if attributes_str:
							line += f'>{text}'
						else:
							line += f'{text}'
					line += '/>'
					formatted_text.append(line)

				# Process children regardless
				for child in node.children:
					process_node(child, depth + 1)

			elif isinstance(node, DOMTextNode):
				# Add text only if it doesn't have a highlighted parent
				if not node.has_parent_with_highlight_index() and node.is_visible:  # and node.is_parent_top_element()
					formatted_text.append(f'{node.text}')

		process_node(self, 0)
		return '\n'.join(formatted_text)

	def get_file_upload_element(self, check_siblings: bool = True) -> Optional['DOMElementNode']:
		# Check if current element is a file input
		if self.tag_name == 'input' and self.attributes.get('type') == 'file':
			return self

		# Check children
		for child in self.children:
			if isinstance(child, DOMElementNode):
				result = child.get_file_upload_element(check_siblings=False)
				if result:
					return result

		# Check siblings only for the initial call
		if check_siblings and self.parent:
			for sibling in self.parent.children:
				if sibling is not self and isinstance(sibling, DOMElementNode):
					result = sibling.get_file_upload_element(check_siblings=False)
					if result:
						return result

		return None

def process_node(node: DOMBaseNode, depth: int) -> None:
	if isinstance(node, DOMElementNode):
		# Add element with highlight_index
		if node.highlight_index is not None:
			attributes_str = ''
			text = node.get_all_text_till_next_clickable_element()
			if include_attributes:
				attributes = list(
					set(
						[
							str(value)
							for key, value in node.attributes.items()
							if key in include_attributes and value != node.tag_name
						]
					)
				)
				if text in attributes:
					attributes.remove(text)
				attributes_str = ';'.join(attributes)
			line = f'[{node.highlight_index}]<{node.tag_name} '
			if attributes_str:
				line += f'{attributes_str}'
			if text:
				if attributes_str:
					line += f'>{text}'
				else:
					line += f'{text}'
			line += '/>'
			formatted_text.append(line)

		# Process children regardless
		for child in node.children:
			process_node(child, depth + 1)

	elif isinstance(node, DOMTextNode):
		# Add text only if it doesn't have a highlighted parent
		if not node.has_parent_with_highlight_index() and node.is_visible:  # and node.is_parent_top_element()
			formatted_text.append(f'{node.text}')

def count_string_tokens(string: str, model: str) -> tuple[int, float]:
	"""Count the number of tokens in a string using a specified model."""

	def get_price_per_token(model: str) -> float:
		"""Get the price per token for a specified model.

		@todo: move to utils, use a package or sth
		"""
		prices = {
			'gpt-4o': 2.5 / 1e6,
			'gpt-4o-mini': 0.15 / 1e6,
		}
		return prices[model]

	llm = ChatOpenAI(model=model)
	token_count = llm.get_num_tokens(string)
	price = token_count * get_price_per_token(model)
	return token_count, price

